namespace doc_example_ApplicationWindowHandle_1 {
// compile only
struct Editor final : gf::Component {
    std::shared_ptr<gf::Panel> root = gf::make_control<gf::Panel>(gf::StableId("editor"));
    std::shared_ptr<gf::Button> quit =
        gf::make_control<gf::Button>(gf::StableId("editor.quit"), "&Quit");
    gf::ApplicationWindowHandle handle;

    Editor() {
        (*quit).set_bounds({16.0, 16.0, 96.0, 28.0});
        (*root).add_child(quit);
        gf::on((*quit).clicked(), *this, &Editor::on_quit);
    }
    void on_quit() {
        static_cast<void>(handle.request_close());   // closing may still cancel
    }
};

struct KeepHandle final {
    Editor* editor;
    void operator()(gf::Window&, gf::ApplicationWindowHandle window_handle) const {
        (*editor).handle = window_handle;
    }
};

void example() {
    Editor editor;
    gf::ApplicationWindowOptions options;
    options.title = "Editor";
    options.ready = KeepHandle{&editor};
    gf::ApplicationResult result = gf::Application::run(
        std::make_unique<gf::Window>(editor.root, gf::Size{640.0, 480.0}), std::move(options));
    static_cast<void>(result);
}
}  // namespace doc_example_ApplicationWindowHandle_1

namespace doc_example_ApplicationWindowOptions_1 {
// compile only
struct ConfirmClose final {
    bool* unsaved;
    void operator()(gf::HostCloseRequest& request) const { request.cancel = *unsaved; }
};

struct ShowDocumentTitle final {
    void operator()(gf::Window&, gf::ApplicationWindowHandle handle) const {
        static_cast<void>(handle.set_title("Untitled - Notes"));
    }
};

void example() {
    bool unsaved_changes = false;
    std::shared_ptr<gf::Panel> root = gf::make_control<gf::Panel>(gf::StableId("notes"));
    gf::ApplicationWindowOptions options;
    options.title = "Notes";
    options.initial_size = {800.0, 600.0};
    options.ready = ShowDocumentTitle{};
    options.closing = ConfirmClose{&unsaved_changes};
    gf::ApplicationResult result = gf::Application::run(
        std::make_unique<gf::Window>(root, gf::Size{800.0, 600.0}), std::move(options));
    static_cast<void>(result);
}
}  // namespace doc_example_ApplicationWindowOptions_1

namespace doc_example_DropDownButton_2 {
// compile only
struct ExportButton final : gf::Component {
    gf::ContextMenu menu{"export.menu"};
    std::shared_ptr<gf::DropDownButton> button =
        gf::make_control<gf::DropDownButton>(gf::StableId("export"), "&Export");

    ExportButton() {
        menu.set_items({gf::MenuItemSpec(
            "export.pdf", gf::MenuItemKind::command,
            std::make_shared<gf::Command>("export.pdf", "PDF"), "PDF")});
        gf::on((*button).drop_down_requested(), *this, &ExportButton::open_menu);
        gf::on((*button).drop_down_close_requested(), *this, &ExportButton::close_menu);
        gf::on(menu.open_changed(), *this, &ExportButton::menu_open_changed);
    }
    void open_menu(gf::DropDownButton& source) {
        const gf::Rect bounds = source.absolute_bounds();
        menu.show(source.shared_from_this(), gf::Point{bounds.x, bounds.y + bounds.height},
                  gf::MenuOpenMode::pointer);
    }
    void close_menu() { menu.close(); }
    void menu_open_changed(bool open) { (*button).set_drop_down_open(open); }
};

void example() { ExportButton exporter; }
}  // namespace doc_example_DropDownButton_2
